def normal(p,action,ch,n,deck,alternate=None):
    """Keep positive normal commands and explicit negative release aliases."""
    add(p,action,ch,n,deck=deck);p['inputs'][-1]['shifted']=False
    if alternate is not None:
        add(p,action,ch,alternate,deck=deck);p['inputs'][-1]['releaseOnly']=True
    for off in [n]+([] if alternate is None else [alternate]):
        add(p,action,((ch-1+2)%4)+1,off,deck=deck);p['inputs'][-1]['releaseOnly']=True


def djtech_legacy_profiles():
    """Return the two own-model manual normal layouts with separate identities."""
    results=[]
    for name,dragon in [('DJ-Tech DRAGON TWO',True),('DJ-Tech 4MIX',False)]:
        ref=DJTECH_LEGACY_REFERENCES[name];p=profile(name,ref['url'])
        p.update(autoSelect=False,definition='manufacturer:djtech-'+('dragon-two' if dragon else '4mix-pitch')+'-manual-normal',
            aliases=([name,'DJ-Tech Dragon Two','DRAGON TWO','DRAGON2'] if dragon else [name,'DJ-Tech 4-Mix Pitch','4MIX','4-Mix Pitch']),
            excludedAliases=(['4MIX','DJ-Tech 4MIX','DJ-Tech Reloaded','I-Mix Reload'] if dragon else ['DRAGON TWO','DJ-Tech DRAGON TWO','I-Mix Reload','4MIX non-Pitch preset']),
            hardwareMode=('Manual DRAGON TWO four-deck MIDI mixing on an exposed source. Use explicit raw1..4 channels and configure app audio separately. Physical analogue/two-deck modes need separate qualification.' if dragon else 'Manual own 4MIX Pitch layout on an exposed source, explicit raw1..4 channels. Configure app audio separately. Global mixer/Load/PFL channel and other presets remain unqualified.')+' C/D require app opt-in. Positive shifted commands stay inactive.',
            scope=('Manual220-input four-target normal transport/held Cue/bends, Load/PFL, manual loops, four Hot Cues and six mixer controls per deck.' if dragon else 'Manual164-input four-target normal transport/held Cue, manual loops and four Hot Cues in the own Pitch layout.')+' Explicit Shift/opposite-bank negative release guards. No automatic identity, global-channel guess, output or audio route.',
            gaps=[ref['review']])
        for ch,deck in enumerate('abcd',1):
            add(p,'shift',ch,24 if dragon else 14);p['inputs'][-1]['shiftInput']=(ch-1)%2
            buttons=([('play',23,None),('cuePreview',22,None),('sync',16,80),('load',8,None),('cue',9,None),('loopIn',13,77),('loopOut',14,78),('reloop',15,79),('pitchBendDown',11,75),('pitchBendUp',12,76)] if dragon else [('play',12,76),('cuePreview',11,75),('sync',5,69),('loopIn',2,66),('loopOut',3,67),('reloop',4,68)])
            for action,n,alt in buttons:normal(p,action,ch,n,deck,alt)
            for slot in range(4):
                n=(17 if dragon else 6)+slot;normal(p,'hotcue'+str(slot+1),ch,n,deck,n+64)
            if dragon:
                for action,n in [('gain',8),('high',25),('mid',26),('low',27),('filterKnob',28),('level',9)]:
                    add(p,action,ch,n,'control',deck=deck)
        results.append(p)
    return results
